function looksLikePhone(text) {
  const bare = String(text == null ? '' : text).replace(REFERENCE, ' ');
  return (bare.match(/\+?\d[\d\s().-]{5,}\d/g) || []).some((m) => m.replace(/\D/g, '').length >= 7);
}

