    const t = new Date(r[field]).getTime();
    if (Number.isFinite(t) && t < new Date(cutoff).getTime()) old.push(r.id);
  }
  return { cutoff, ids: old.slice(0, limit), found: old.length, capped: old.length > limit };
}

